steps.action:
curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query {
    users(first: 20) {
      nodes {
        id
        name
        email
      }
    }
    teams(first: 50) {
      nodes {
        id
        name
        key
        projects(first: 50) {
          nodes {
            id
            name
          }
        }
      }
    }
  }"
}'
